func (s *selectionObservation) UnmarshalJSON(raw []byte) error {
	type document selectionObservation
	var decoded document
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return err
	}
	*s = selectionObservation(decoded)
	s.Raw = append([]byte(nil), raw...)
	return nil
}
func selectionShapeJSON(shape accessorShape) any {
	value := map[string]any{"kind": shape.Kind}
	switch shape.Kind {
	case "primitive":
		value["name"] = shape.Name
	case "enum":
		value["variants"] = shape.Variants
	case "optional":
		if shape.Of != nil {
			value["of"] = selectionShapeJSON(*shape.Of)
		}
	}
	return value
}
func selectionPlanJSON(plan accessorPlan) any {
	field := func(field accessorField) any { return map[string]any{"name": field.Name, "type": field.Type} }
	nodes := make([]any, 0, len(plan.Nodes))
	for _, node := range plan.Nodes {
		op := node.Operation
		operation := map[string]any{"kind": op.Kind}
		switch op.Kind {
		case "field":
			operation["field"] = field(op.Field)
			operation["next"] = op.Next
		case "optional", "newtype":
			operation["next"] = op.Next
		case "union":
			operation["tag"] = op.Tag
			operation["variants"] = op.Variants
		}
		nodes = append(nodes, map[string]any{"source": node.Source, "shape": selectionShapeJSON(node.Shape), "position": node.Position, "operation": operation, "leaf": node.Leaf, "may_miss": node.MayMiss, "depth": node.Depth})
	}
	return map[string]any{"segments": plan.Segments, "root": field(plan.Root), "start": plan.Start, "nodes": nodes}
}
func selectionFactsJSON(facts accessorTypeFacts) any {
	nodes := map[string]any{}
	for name, body := range facts.Nodes {
		value := map[string]any{"kind": body.Kind}
		switch body.Kind {
		case "newtype":
			value["of"] = body.Of
		case "struct", "union":
			value["members"] = body.Members
		}
		nodes[name] = value
	}
	return map[string]any{"nodes": nodes}
}
func selectionJSON(value any) any {
	raw, _ := json.Marshal(value)
	var answer any
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.UseNumber()
	_ = decoder.Decode(&answer)
	return answer
}
func (s selectionObservation) transparent(source string) (string, error) {
	seen := map[string]bool{}
	for depth := 0; depth < 128; depth++ {
		body, ok := s.Declarations[source]
		if !ok || body.Kind != "newtype" {
			return source, nil
		}
		if seen[source] {
			return "", fmt.Errorf("recursive selection alias")
		}
		seen[source] = true
		source = body.Of
	}
	return "", fmt.Errorf("selection alias bound")
}
func (s selectionObservation) shape(source string, depth int) (accessorShape, error) {
	if depth > 128 {
		return accessorShape{}, fmt.Errorf("selection shape bound")
	}
	source, err := s.transparent(source)
	if err != nil {
		return accessorShape{}, err
	}
	if inner, ok := accessorOptional(source); ok {
		shape, err := s.shape(inner, depth+1)
		if shape.Kind == "optional" {
			return shape, err
		}
		return accessorShape{Kind: "optional", Of: &shape}, err
	}
	if accessorPrimitive(source) {
		return accessorShape{Kind: "primitive", Name: strings.ToLower(source)}, nil
	}
	if strings.HasPrefix(source, "List<") {
		return accessorShape{Kind: "sequence"}, nil
	}
	if strings.HasPrefix(source, "Map<") {
		return accessorShape{Kind: "object"}, nil
	}
	body, ok := s.Declarations[source]
	if !ok {
		return accessorShape{}, fmt.Errorf("missing selection shape")
	}
	if body.Kind == "enum" {
		var variants []string
		if err := json.Unmarshal(body.Variants, &variants); err != nil {
			return accessorShape{}, err
		}
		return accessorShape{Kind: "enum", Variants: variants}, nil
	}
	return accessorShape{Kind: "object"}, nil
}
func (s selectionObservation) typeFacts(source string) (accessorTypeFacts, error) {
	facts := accessorTypeFacts{Nodes: map[string]accessorTypeBody{}}
	pending := []string{source}
	for len(pending) > 0 {
		ty := pending[len(pending)-1]
		pending = pending[:len(pending)-1]
		if inner, ok := accessorOptional(ty); ok {
			pending = append(pending, inner)
			continue
		}
		if inner, ok, err := accessorCollection(ty); err != nil {
			return facts, err
		} else if ok {
			pending = append(pending, inner)
			continue
		}
		if accessorPrimitive(ty) {
			continue
		}
		if _, ok := facts.Nodes[ty]; ok {
			continue
		}
		body, ok := s.Declarations[ty]
		if !ok {
			return facts, fmt.Errorf("missing selection type fact")
		}
		node := accessorTypeBody{Kind: body.Kind, Of: body.Of}
		switch body.Kind {
		case "newtype":
			pending = append(pending, body.Of)
		case "struct":
			for _, field := range body.Fields {
				node.Members = append(node.Members, field.Type)
				pending = append(pending, field.Type)
			}
		case "union":
			var variants map[string]string
			if err := json.Unmarshal(body.Variants, &variants); err != nil {
				return facts, err
			}
			for _, name := range meaningKeys(selectionJSON(variants).(map[string]any)) {
				node.Members = append(node.Members, variants[name])
				pending = append(pending, variants[name])
			}
		case "enum":
		default:
			return facts, fmt.Errorf("invalid selection declaration")
		}
		facts.Nodes[ty] = node
		if len(facts.Nodes) > 4096 {
			return facts, fmt.Errorf("selection fact bound")
		}
	}
	return facts, nil
}
func (s selectionObservation) checkPlan(plan accessorPlan, item bool) error {
	if plan.Start < 0 || plan.Start >= len(plan.Nodes) || plan.Nodes[plan.Start].Leaf == nil {
		return fmt.Errorf("selection invalid plan root")
	}
	target := *plan.Nodes[plan.Start].Leaf
	if plan.Nodes[plan.Start].MayMiss {
		if _, ok := accessorOptional(target); !ok {
			target = "Optional<" + target + ">"
		}
	}
	facts, err := s.typeFacts(target)
	if err != nil {
		return err
	}
	if _, err = admitAccessorMode(selectionJSON(map[string]any{"plan": selectionPlanJSON(plan), "target": target, "types": selectionFactsJSON(facts)}), item); err != nil {
		return err
	}
	for _, node := range plan.Nodes {
		shape, err := s.shape(node.Source, 0)
		if err != nil {
			return err
		}
		if !reflect.DeepEqual(shape, node.Shape) {
			return fmt.Errorf("selection declared shape disagrees")
		}
		body := s.Declarations[node.Source]
		switch op := node.Operation; op.Kind {
		case "field":
			if body.Kind != "struct" {
				return fmt.Errorf("selection field owner differs")
			}
			found := false
			for _, field := range body.Fields {
				if field.Name == op.Field.Name && field.Type == op.Field.Type {
					found = true
				}
			}
			if !found {
				return fmt.Errorf("selection undeclared field")
			}
		case "newtype":
			if body.Kind != "newtype" || body.Of != plan.Nodes[op.Next].Source {
				return fmt.Errorf("selection alias differs")
			}
		case "union":
			var variants map[string]string
			if body.Kind != "union" || body.Tag != op.Tag || json.Unmarshal(body.Variants, &variants) != nil || len(variants) != len(op.Variants) {
				return fmt.Errorf("selection union differs")
			}
			for label, index := range op.Variants {
				if variants[label] != plan.Nodes[index].Source {
					return fmt.Errorf("selection variant differs")
				}
			}
		case "missing":
			if body.Kind != "struct" {
				return fmt.Errorf("selection missing member owner differs")
			}
			for _, field := range body.Fields {
				if field.Name == plan.Segments[node.Position] {
					return fmt.Errorf("selection omitted an existing field")
				}
			}
		}
	}
	return nil
}

type periodicOperation struct {
	eligible                   bool
	received                   uint64
	invoked, failed, completed bool
}
type periodicLedger struct {
	check                   PeriodicCheck
	opened                  PeriodicOpened
	period                  uint64
	operations              map[uint64]*periodicOperation
	invocations             map[string]bool
	dropped                 map[uint64]bool
	cursor, through, lastAt uint64
}

func (l *periodicLedger) deadline(ordinal uint64) (uint64, bool) {
	if ordinal == 0 || ordinal > (^uint64(0)-l.opened.AnchorMillis)/l.period {
		return 0, false
	}
	return l.opened.AnchorMillis + ordinal*l.period, true
}
func (l *periodicLedger) observe(o PeriodicObservation, hold uint64, closed *uint64) error {
	if len(o.Records) > 4096 || o.Cursor > 4096 || o.Cursor != l.cursor+uint64(len(o.Records)) {
		return fmt.Errorf("PeriodicResource: capture cursor")
	}
	if o.ElapsedMillis < hold || o.CompleteThroughMillis < hold || o.CompleteThroughMillis > o.ElapsedMillis || o.CompleteThroughMillis < l.through {
		return fmt.Errorf("PeriodicObservation: incomplete held window")
	}
	for _, record := range o.Records {
		if record.Scope != l.opened.Scope {
			return fmt.Errorf("PeriodicOrigin: wrong binding, scenario or lifetime")
		}
		f := record.Fact
		if f.AtMillis < l.lastAt || f.AtMillis <= l.through || f.AtMillis > o.CompleteThroughMillis {
			return fmt.Errorf("PeriodicObservation: invalid fact time/order")
		}
		if closed != nil && f.AtMillis >= *closed && f.Kind != "independent" {
			return fmt.Errorf("PeriodicLifetime: occurrence after stop")
		}
		l.lastAt = f.AtMillis
		busy := false
		for _, op := range l.operations {
			if !op.completed {
				busy = true
			}
		}
		switch f.Kind {
		case "received":
			due, ok := l.deadline(f.Ordinal)
			if !ok || due != f.DueMillis || f.AtMillis < due || l.operations[f.Ordinal] != nil || l.dropped[f.Ordinal] {
				return fmt.Errorf("PeriodicOccurrence: early, duplicate or incorrect tick")
			}
			if busy {
				return fmt.Errorf("PeriodicOverlap: concurrent poll")
			}
			eligible := !(l.check.Fixture == "initially_inactive" && f.Ordinal == 1)
			if f.Eligible != eligible {
				return fmt.Errorf("PeriodicHost: eligibility fixture")
			}
			l.operations[f.Ordinal] = &periodicOperation{eligible: eligible, received: f.AtMillis}
		case "read_failed":
			op := l.operations[f.Ordinal]
			if op == nil || !op.eligible || op.invoked || op.failed || op.completed || l.check.Fixture != "first_read_fails" || f.Ordinal != 1 {
				return fmt.Errorf("PeriodicHost: unexpected read failure")
			}
			op.failed = true
		case "invoked":
			op := l.operations[f.Ordinal]
			if op == nil || !op.eligible || op.failed || op.invoked || op.completed || f.Command != l.check.Command || f.Invocation == "" || l.invocations[f.Invocation] || f.AtMillis < op.received {
				return fmt.Errorf("PeriodicInvocation: duplicated, misattributed or forbidden invocation")
			}
			if err := periodicFields(l.check.Periodic.Host.ReadFields, f.Read); err != nil {
				return err
			}
			expected := map[string]Node{}
			for target, source := range l.check.Mapping {
				table := f.Read
				if source.Kind == "context" {
					table = l.opened.Context
				}
				value, ok := table[source.Field]
				if !ok {
					return fmt.Errorf("PeriodicHost: missing value")
				}
				expected[target] = value
			}
			if !equal(f.Input, expected) {
				return fmt.Errorf("PeriodicMapping: invocation differs from current host inputs")
			}
			op.invoked = true
			l.invocations[f.Invocation] = true
		case "completed":
			third, valid := l.deadline(3)
			if l.check.Fixture == "slow_first_read" && f.Ordinal == 1 && (!valid || f.AtMillis <= third) {
				return fmt.Errorf("PeriodicHost: first read did not remain busy through both missed deadlines")
			}
			op := l.operations[f.Ordinal]
			if op == nil || op.completed || (op.eligible && !op.invoked && !op.failed) || (l.check.Fixture == "first_read_fails" && f.Ordinal == 1 && !op.failed) {
				return fmt.Errorf("PeriodicOccurrence: missing attempt")
			}
			op.completed = true
		case "dropped":
			if f.First == 0 || f.First > f.Last || f.Last > 5 || l.check.Fixture != "slow_first_read" || !busy {
				return fmt.Errorf("PeriodicMissed: loss outside busy window")
			}
			for n := f.First; n <= f.Last; n++ {
				due, ok := l.deadline(n)
				if !ok || due > f.AtMillis || l.operations[n] != nil || l.dropped[n] {
					return fmt.Errorf("PeriodicMissed: invalid dropped ordinal")
				}
				l.dropped[n] = true
			}
		case "independent":
			if f.Invocation == "" || f.Command != l.check.Command || l.invocations[f.Invocation] {
				return fmt.Errorf("PeriodicOrigin: invalid independent invocation")
			}
			l.invocations[f.Invocation] = true
		default:
			return fmt.Errorf("PeriodicObservation: unknown fact")
		}
	}
	l.cursor = o.Cursor
	l.through = o.CompleteThroughMillis
	{
		liveThrough := l.through
		if closed != nil {
			liveThrough = *closed
			if liveThrough > 0 {
				liveThrough--
			}
		}
		var due uint64
		if liveThrough > l.opened.AnchorMillis {
			due = (liveThrough - l.opened.AnchorMillis) / l.period
		}
		if due > 5 {
			return fmt.Errorf("PeriodicResource: live observation exceeds five-period witness")
		}
		if l.check.Fixture == "slow_first_read" && due >= 4 {
			pending, dropped := 0, 0
			for _, n := range []uint64{2, 3} {
				if op := l.operations[n]; op != nil && op.completed {
					pending++
				}
				if l.dropped[n] {
					dropped++
				}
			}
			if pending != 1 || dropped != 1 {
				return fmt.Errorf("PeriodicMissed: exactly one pending and one discarded tick required")
			}
		}
		for n := uint64(1); n <= due; n++ {
			if l.check.Fixture == "slow_first_read" && (n == 2 || n == 3) {
				continue
			}
			op := l.operations[n]
			if op == nil {
				return fmt.Errorf("PeriodicLiveness: missing idle occurrence")
			}
			deadline, _ := l.deadline(n)
			if op.received != deadline {
				return fmt.Errorf("PeriodicLateness: idle receipt delayed")
			}
			if !(l.check.Fixture == "slow_first_read" && n == 1 && due < 4) && !op.completed {
				return fmt.Errorf("PeriodicLiveness: missing completion")
			}
		}
	}
	return nil
}

func periodicSnapshot[T any](value T) (T, error) {
	var copied T
	encoded, err := json.Marshal(value)
	if err != nil {
		return copied, err
	}
	decoder := json.NewDecoder(bytes.NewReader(encoded))
	decoder.UseNumber()
	err = decoder.Decode(&copied)
	return copied, err
}

// CheckPeriodic exercises real authority and a controlled target clock without wall sleeps.
func CheckPeriodic(check PeriodicCheck, correlation string, target PeriodicTarget, clock Clock) (result error) {
	if err := validatePeriodic(check); err != nil {
		return err
	}
	mark := InstantMark{Instant: "periodic-anchor", Correlation: correlation}
	if err := clock.MarkInstant(mark); err != nil {
		return fromCallback(err)
	}
	requestCheck, err := periodicSnapshot(check)
	if err != nil {
		return err
	}
	opened, err := target.OpenPeriodic(PeriodicOpen{Check: requestCheck, Mark: mark})
	if err != nil {
		return fromCallback(err)
	}
	stopped := false
	defer func() {
		if !stopped {
			_, closeErr := target.ClosePeriodic(opened.Scope)
			if result == nil {
				result = fromCallback(closeErr)
			}
		}
	}()
	if opened.Scope.Correlation != correlation || opened.Scope.Binding != check.Binding || opened.Scope.Lifetime == "" || len(opened.Scope.Lifetime) > 128 {
		return fmt.Errorf("PeriodicOrigin: invalid opened scope")
	}
	if err = periodicFields(check.Periodic.Host.ContextFields, opened.Context); err != nil {
		return err
	}
	opened.Context, err = periodicSnapshot(opened.Context)
	if err != nil {
		return err
	}
	if opened.AnchorMillis%1000 != 0 {
		return fmt.Errorf("%w: whole-second controlled anchor required", ErrUnsupported)
	}
	p, _ := periodicSeconds(check.Periodic.Every)
	anchor := opened.AnchorMillis / 1000
	if anchor > 4294967295-4*p {
		return fmt.Errorf("PeriodicResource: anchor overflow")
	}
	ledger := periodicLedger{check: check, opened: opened, period: p * 1000, operations: map[uint64]*periodicOperation{}, invocations: map[string]bool{}, dropped: map[uint64]bool{}, through: opened.AnchorMillis, lastAt: opened.AnchorMillis}
	for _, offset := range []uint64{p - 1, p, 2 * p, 4 * p} {
		seconds := anchor + offset
		o, e := target.ObservePeriodic(PeriodicObserve{Scope: opened.Scope, Elapsed: ElapsedRequest{Instant: mark.Instant, Hold: int(seconds), Correlation: correlation}, After: ledger.cursor})
		if e != nil {
			return fromCallback(e)
		}
		if e = ledger.observe(o, seconds*1000, nil); e != nil {
			return e
		}
	}
	closed, err := target.ClosePeriodic(opened.Scope)
	stopped = true
	if err != nil {
		return fromCallback(err)
	}
	if closed.Scope != opened.Scope || closed.AtMillis < ledger.through {
		return fmt.Errorf("PeriodicLifetime: invalid stop acknowledgement")
	}
	if closed.AtMillis > 4294967295*1000-p*1000 {
		return fmt.Errorf("PeriodicResource: closure overflow")
	}
	hold := (closed.AtMillis + p*1000 + 999) / 1000
	o, err := target.ObservePeriodic(PeriodicObserve{Scope: opened.Scope, Elapsed: ElapsedRequest{Instant: mark.Instant, Hold: int(hold), Correlation: correlation}, After: ledger.cursor})
	if err != nil {
		return fromCallback(err)
	}
	return ledger.observe(o, hold*1000, &closed.AtMillis)
}
func (r *run) checkPeriodic(index int, step Step) bool {
	target, ok := r.target.(PeriodicTarget)
	if !ok {
		r.skip("step %d: target has no periodic authority", index)
		return false
	}
	clock, ok := r.clock(index)
	if !ok {
		return false
	}
	if step.Check == nil {
		return r.fail(index, "missing periodic check")
	}
	if err := CheckPeriodic(*step.Check, r.correlation, target, clock); err != nil {
		var callback callbackError
		if errors.As(err, &callback) {
			return r.targetFailure(index, err, "periodic callback")
		}
		if errors.Is(err, ErrUnsupported) {
			r.skip("step %d: periodic authority/observation unsupported: %v", index, err)
			return false
		}
		return r.fail(index, "periodic contract: %v", err)
	}
	return true
}

func (s selectionObservation) checkPredicate(condition predicate, reads map[string]accessorPlan, count *int, used map[string]bool) error {
	*count++
	if *count > 64 {
		return fmt.Errorf("selection predicate bound")
	}
	switch condition.kind {
	case "always", "never":
		return nil
	case "all", "any":
		for _, child := range condition.children {
			if err := s.checkPredicate(child, reads, count, used); err != nil {
				return err
			}
		}
		return nil
	case "not":
		if condition.body == nil {
			return fmt.Errorf("selection predicate child missing")
		}
		return s.checkPredicate(*condition.body, reads, count, used)
	case "defined", "compare":
		path := condition.path
		if condition.kind == "compare" {
			if !condition.left.isFact || condition.right.isFact || (condition.op != "==" && condition.op != "!=") {
				return fmt.Errorf("selection requires fact/literal Eq/Ne")
			}
			path = condition.left.path
			literal, ok := condition.right.literal.(string)
			if !ok {
				return fmt.Errorf("selection literal must be text")
			}
			plan, ok := reads[path]
			if !ok || plan.Start < 0 || plan.Start >= len(plan.Nodes) || plan.Nodes[plan.Start].Leaf == nil {
				return fmt.Errorf("selection read is undeclared")
			}
			ty := *plan.Nodes[plan.Start].Leaf
			for depth := 0; depth < 128; depth++ {
				var err error
				ty, err = s.transparent(ty)
				if err != nil {
					return err
				}
				if inner, ok := accessorOptional(ty); ok {
					ty = inner
					continue
				}
				break
			}
			if body, ok := s.Declarations[ty]; ok && body.Kind == "enum" {
				var variants []string
				if err := json.Unmarshal(body.Variants, &variants); err != nil {
					return err
				}
				valid := false
				for _, variant := range variants {
					if literal == variant {
						valid = true
					}
				}
				if !valid {
					return fmt.Errorf("selection enum literal is undeclared")
				}
			}
		}
		if _, ok := reads[path]; !ok || !strings.HasPrefix(path, "item.") {
			return fmt.Errorf("selection predicate read undeclared")
		}
		used[path] = true
		return nil
	}
	return fmt.Errorf("unsupported selection predicate")
}
func admitSelection(value any) (*selectionObservation, error) {
	f, err := closed(value, "event_type plan declarations selector projection", "")
	if err != nil {
		return nil, err
	}
	if err = name(f["event_type"], false); err != nil {
		return nil, err
	}
	p, err := closed(f["plan"], "inputs selectors", "")
	if err != nil {
		return nil, err
	}
	inputs, err := array(p["inputs"])
	if err != nil || len(inputs) > 4 {
		return nil, fmt.Errorf("selection input bound")
	}
	selectors, err := array(p["selectors"])
	if err != nil || len(selectors) > 8 {
		return nil, fmt.Errorf("selection selector bound")
	}
	raw, err := json.Marshal(value)
	if err != nil || len(raw) > 1048576 {
		return nil, fmt.Errorf("selection byte bound")
	}
	var s selectionObservation
	if err = json.Unmarshal(raw, &s); err != nil {
		return nil, err
	}
	if s.Selector < 0 || s.Selector >= len(selectors) {
		return nil, fmt.Errorf("selection output index invalid")
	}
	declarations, ok := f["declarations"].(map[string]any)
	if !ok || len(declarations) > 4096 {
		return nil, fmt.Errorf("selection declaration bound")
	}
	for name_, rawBody := range declarations {
		if err = name(name_, false); err != nil {
			return nil, err
		}
		body := s.Declarations[name_]
		required := "kind"
		switch body.Kind {
		case "newtype":
			required += " of"
		case "struct":
			required += " fields"
		case "enum":
			required += " variants"
		case "union":
			required += " tag variants"
		default:
			return nil, fmt.Errorf("unsupported selection declaration")
		}
		fields, err := closed(rawBody, required, "")
		if err != nil {
			return nil, err
		}
		if body.Kind == "struct" {
			members, err := array(fields["fields"])
			if err != nil || len(members) > 4096 {
				return nil, fmt.Errorf("selection field bound")
			}
			seen := map[string]bool{}
			for _, field := range members {
				if err = admitAccessorField(field); err != nil {
					return nil, err
				}
				name_ := field.(map[string]any)["name"].(string)
				if seen[name_] {
					return nil, fmt.Errorf("duplicate selection field")
				}
				seen[name_] = true
			}
		}
	}
	names := map[string]bool{}
	for index, rawInput := range inputs {
		fields, err := closed(rawInput, "name source list_type item_type optional_items conversion", "")
		if err != nil {
			return nil, err
		}
		input := s.Plan.Inputs[index]
		if !regexp.MustCompile(`^_*[A-Za-z][A-Za-z0-9_]*$`).MatchString(input.Name) || names[input.Name] {
			return nil, fmt.Errorf("invalid selection input name")
		}
		names[input.Name] = true
		if input.Conversion != nil {
			return nil, fmt.Errorf("selection-input-conversion requires host implementation")
		}
		list, err := s.transparent(input.ListType)
		if err != nil || !strings.HasPrefix(list, "List<") || !strings.HasSuffix(list, ">") {
			return nil, fmt.Errorf("selection requires required List")
		}
		originalItem := list[5 : len(list)-1]
		item, err := s.transparent(originalItem)
		if err != nil {
			return nil, err
		}
		optional := false
		if inner, ok := accessorOptional(item); ok {
			optional = true
			item = inner
		} else {
			item = originalItem
		}
		if item != input.ItemType || optional != input.OptionalItems {
			return nil, fmt.Errorf("selection item type differs")
		}
		present, err := s.transparent(item)
		if err != nil {
			return nil, err
		}
		if kind := s.Declarations[present].Kind; kind != "struct" && kind != "union" {
			return nil, fmt.Errorf("selection item requires record")
		}
		source, ok := fields["source"].(map[string]any)
		if !ok {
			return nil, fmt.Errorf("selection source shape")
		}
		sourceType := ""
		switch input.Source.Kind {
		case "field":
			if _, err = closed(source, "kind field", ""); err != nil {
				return nil, err
			}
			if err = admitAccessorField(source["field"]); err != nil {
				return nil, err
			}
			sourceType = input.Source.Field.Type
		case "accessor":
			if _, err = closed(source, "kind plan", ""); err != nil {
				return nil, err
			}
			if err = s.checkPlan(input.Source.Plan, false); err != nil {
				return nil, err
			}
			sourceType = *input.Source.Plan.Nodes[input.Source.Plan.Start].Leaf
			if input.Source.Plan.Nodes[input.Source.Plan.Start].MayMiss {
				if _, ok := accessorOptional(sourceType); !ok {
					sourceType = "Optional<" + sourceType + ">"
				}
			}
		default:
			return nil, fmt.Errorf("invalid selection source kind")
		}
		if sourceType != input.ListType {
			return nil, fmt.Errorf("selection source/list type mismatch")
		}
	}
	names = map[string]bool{}
	total := 0
	for index, rawSelector := range selectors {
		fields, err := closed(rawSelector, "name input operation", "")
		if err != nil {
			return nil, err
		}
		selector := s.Plan.Selectors[index]
		if !regexp.MustCompile(`^_*[A-Za-z][A-Za-z0-9_]*$`).MatchString(selector.Name) || names[selector.Name] || selector.Input < 0 || selector.Input >= len(inputs) {
			return nil, fmt.Errorf("selection identity invalid")
		}
		names[selector.Name] = true
		operation := selector.Operation
		required := "kind"
		var prior []int
		switch operation.Kind {
		case "first":
			required += " excluding predicate reads"
			prior = operation.Excluding
		case "first_present":
			required += " selections"
			prior = operation.Selections
			if len(prior) == 0 {
				return nil, fmt.Errorf("empty first_present")
			}
		default:
			return nil, fmt.Errorf("unsupported selector")
		}
		op, err := closed(fields["operation"], required, "")
		if err != nil {
			return nil, err
		}
		if len(prior) > 4 {
			return nil, fmt.Errorf("selection reference bound")
		}
		seen := map[int]bool{}
		for _, previous := range prior {
			if previous < 0 || previous >= index || seen[previous] || s.Plan.Selectors[previous].Input != selector.Input {
				return nil, fmt.Errorf("selection reference is not earlier same input")
			}
			seen[previous] = true
		}
		if operation.Kind == "first" {
			if err = admitPredicateEnvelope(op["predicate"], 0); err != nil {
				return nil, err
			}
			if len(operation.Reads) > 64 {
				return nil, fmt.Errorf("selection read bound")
			}
			for path, plan := range operation.Reads {
				if strings.Join(plan.Segments, ".") != path || plan.Root.Type != s.Plan.Inputs[selector.Input].ItemType {
					return nil, fmt.Errorf("selection read identity differs")
				}
				if err = s.checkPlan(plan, true); err != nil {
					return nil, err
				}
				leaf, err := s.transparent(*plan.Nodes[plan.Start].Leaf)
				if err != nil {
					return nil, err
				}
				for {
					inner, ok := accessorOptional(leaf)
					if !ok {
						break
					}
					leaf, err = s.transparent(inner)
					if err != nil {
						return nil, err
					}
				}
				if leaf != "String" && s.Declarations[leaf].Kind != "enum" {
					return nil, fmt.Errorf("selection predicate requires String or enum")
				}
			}
			condition, err := fromNode(op["predicate"])
			if err != nil {
				return nil, err
			}
			count := 0
			used := map[string]bool{}
			if err = s.checkPredicate(condition, operation.Reads, &count, used); err != nil {
				return nil, err
			}
			if len(used) != len(operation.Reads) {
				return nil, fmt.Errorf("selection contains unused predicate reads")
			}
			total += count
			if total > 256 {
				return nil, fmt.Errorf("selection total predicate bound")
			}
		}
	}
	projection, err := closed(f["projection"], "projection target types", "")
	if err != nil {
		return nil, err
	}
	if err = s.checkPlan(s.Projection.Projection, true); err != nil {
		return nil, err
	}
	if s.Projection.Projection.Root.Type != s.Plan.Inputs[s.Plan.Selectors[s.Selector].Input].ItemType {
		return nil, fmt.Errorf("selection projection item differs")
	}
	if _, ok := accessorOptional(s.Projection.Target); !ok {
		return nil, fmt.Errorf("selection target requires Optional")
	}
	if _, err = admitAccessorMode(map[string]any{"plan": projection["projection"], "target": projection["target"], "types": projection["types"]}, true); err != nil {
		return nil, err
	}
	return &s, nil
}
func selectionFailure(cause string, input, index, selector int) error {
	return fmt.Errorf("SelectionFailure:%s:input=%d:index=%d:selector=%d", cause, input, index, selector)
}
func (s selectionObservation) validateValue(source string, value Node, present bool, bytes *int, depth int) error {
	if depth > 128 || *bytes > 1048576 {
		return fmt.Errorf("resource")
	}
	if inner, ok := accessorOptional(source); ok {
		if !present || value == nil {
			return nil
		}
		return s.validateValue(inner, value, true, bytes, depth+1)
	}
	if s.directMode && source == "Json" && present {
		return directJSON(value, bytes, depth)
	}
	if !present || value == nil {
		return fmt.Errorf("invalid_input")
	}
	if body, ok := s.Declarations[source]; ok {
		switch body.Kind {
		case "newtype":
			return s.validateValue(body.Of, value, true, bytes, depth+1)
		case "enum":
			var variants []string
			if json.Unmarshal(body.Variants, &variants) != nil {
				return fmt.Errorf("invalid_input")
			}
			text, ok := value.(string)
			if !ok {
				return fmt.Errorf("invalid_input")
			}
			for _, variant := range variants {
				if variant == text {
					*bytes += len(text)
					return nil
				}
			}
			return fmt.Errorf("invalid_input")
		case "struct":
			fields, ok := value.(map[string]any)
			if !ok {
				return fmt.Errorf("invalid_input")
			}
			if s.responseMode {
				names := map[string]bool{}
				for _, field := range body.Fields {
					names[field.Name] = true
				}
				for key := range fields {
					if !names[key] {
						return fmt.Errorf("invalid_input")
					}
				}
			}
			for _, field := range body.Fields {
				*bytes += len(field.Name)
				item, present := fields[field.Name]
				if s.directMode {
					if err := directPresence(field, item, present); err != nil {
						return err
					}
				}
				if err := s.validateValue(field.Type, item, present, bytes, depth+1); err != nil {
					return err
				}
			}
			return nil
		case "union":
			fields, ok := value.(map[string]any)
			if !ok {
				return fmt.Errorf("invalid_input")
			}
			label, ok := fields[body.Tag].(string)
			if !ok {
				return fmt.Errorf("invalid_input")
			}
			var variants map[string]string
			if json.Unmarshal(body.Variants, &variants) != nil {
				return fmt.Errorf("invalid_input")
			}
			target, ok := variants[label]
			if !ok {
				return fmt.Errorf("invalid_input")
			}
			key := "value"
			if body.Tag == "value" {
				key = "content"
			}
			if s.responseMode {
				for member := range fields {
					if member != body.Tag && member != key {
						return fmt.Errorf("invalid_input")
					}
				}
			}
			item, present := fields[key]
			return s.validateValue(target, item, present, bytes, depth+1)
		}
	}
	if strings.HasPrefix(source, "List<") && strings.HasSuffix(source, ">") {
		values, ok := value.([]any)
		if !ok {
			return fmt.Errorf("invalid_input")
		}
		limit := 64
		if s.directMode {
			limit = 65536
		}
		if len(values) > limit {
			return fmt.Errorf("resource")
		}
		for _, item := range values {
			if err := s.validateValue(source[5:len(source)-1], item, true, bytes, depth+1); err != nil {
				return err
			}
		}
		return nil
	}
	if s.responseMode && strings.HasPrefix(source, "Map<String, ") && strings.HasSuffix(source, ">") {
		values, ok := value.(map[string]any)
		if !ok {
			return fmt.Errorf("invalid_input")
		}
		limit := 64
		if s.directMode {
			limit = 65536
		}
		if len(values) > limit {
			return fmt.Errorf("resource")
		}
		for key, child := range values {
			*bytes += len(key)
			if err := s.validateValue(source[12:len(source)-1], child, true, bytes, depth+1); err != nil {
				return err
			}
		}
		return nil
	}
	if accessorPrimitive(source) {
		if s.responseMode {
			if !responsePrimitiveAdmits(source, value) {
				return fmt.Errorf("invalid_input")
			}
		} else if source == "Binary64" || source == "Decimal" {
			number, ok := asNumber(value)
			if !ok || math.IsNaN(number) || math.IsInf(number, 0) {
				return fmt.Errorf("invalid_input")
			}
		} else if !accessorShapeAdmits(accessorShape{Kind: "primitive", Name: strings.ToLower(source)}, value) {
			return fmt.Errorf("invalid_input")
		}
		if text, ok := value.(string); ok {
			*bytes += len(text)
			limit := 4096
			if s.directMode {
				limit = 1048576
			}
			if len(text) > limit {
				return fmt.Errorf("resource")
			}
		}
		return nil
	}
	return fmt.Errorf("unsupported")
}
func (s selectionObservation) evaluate(payload map[string]Node) (Node, bool, error) {
	// Admission precedes target execution; direct constructions are checked again here.
	var original any
	decoder := json.NewDecoder(bytes.NewReader(s.Raw))
	decoder.UseNumber()
	if err := decoder.Decode(&original); err != nil {
		return nil, false, fmt.Errorf("selection requires admitted original contract: %w", err)
	}
	admitted, err := admitSelection(original)
	if err != nil {
		return nil, false, err
	}
	// Re-decoding preserves admitted meaning without silently repairing a mutated typed contract.
	retained := *admitted
	retained.Raw = s.Raw
	if !reflect.DeepEqual(s, retained) {
		return nil, false, fmt.Errorf("selection typed contract differs from original")
	}
	s = *admitted
	inputs := make([][]Node, len(s.Plan.Inputs))
	bytes := 0
	for index, input := range s.Plan.Inputs {
		var value Node
		present := false
		if input.Source.Kind == "field" {
			value, present = payload[input.Source.Field.Name]
		} else {
			plan := input.Source.Plan
			target := *plan.Nodes[plan.Start].Leaf
			if plan.Nodes[plan.Start].MayMiss {
				if _, ok := accessorOptional(target); !ok {
					target = "Optional<" + target + ">"
				}
			}
			value, present, err = (accessorObservation{Plan: plan, Target: target}).evaluate(payload)
			if err != nil {
				return nil, false, selectionFailure("invalid_input", index, -1, -1)
			}
		}
		values, ok := value.([]any)
		if !ok || !present {
			return nil, false, selectionFailure("invalid_input", index, -1, -1)
		}
		if len(values) > 64 {
			return nil, false, selectionFailure("resource", index, -1, -1)
		}
		inputs[index] = values
	}
	truth := make([][]bool, len(s.Plan.Selectors))
	for input, values := range inputs {
		for index, item := range values {
			if item == nil && s.Plan.Inputs[input].OptionalItems {
				for selector, plan := range s.Plan.Selectors {
					if plan.Input == input && plan.Operation.Kind == "first" {
						truth[selector] = append(truth[selector], false)
					}
				}
				continue
			}
			if err = s.validateValue(s.Plan.Inputs[input].ItemType, item, true, &bytes, 0); err != nil {
				return nil, false, selectionFailure(err.Error(), input, index, -1)
			}
			for selector, plan := range s.Plan.Selectors {
				if plan.Input != input || plan.Operation.Kind != "first" {
					continue
				}
				observations := factSource{}
				for _, path := range meaningKeys(selectionJSON(plan.Operation.Reads).(map[string]any)) {
					projection := plan.Operation.Reads[path]
					target := *projection.Nodes[projection.Start].Leaf
					if projection.Nodes[projection.Start].MayMiss {
						if _, ok := accessorOptional(target); !ok {
							target = "Optional<" + target + ">"
						}
					}
					value, present, err := (accessorObservation{Plan: projection, Target: target}).evaluate(map[string]Node{"item": item})
					if err != nil {
						return nil, false, selectionFailure("invalid_input", input, index, selector)
					}
					if text, ok := value.(string); ok && present {
						bytes += len(path) + len(text)
						if len(text) > 4096 || bytes > 1048576 {
							return nil, false, selectionFailure("resource", input, index, selector)
						}
						observations[path] = text
					}
				}
				condition, err := fromNode(plan.Operation.Predicate)
				if err != nil {
					return nil, false, err
				}
				answer := condition.evaluate(observations)
				if answer == truthUnknown {
					return nil, false, selectionFailure("unknown", input, index, selector)
				}
				truth[selector] = append(truth[selector], answer == truthTrue)
			}
		}
	}
	selected := make([]int, len(s.Plan.Selectors))
	for index := range selected {
		selected[index] = -1
	}
	for index, selector := range s.Plan.Selectors {
		if selector.Operation.Kind == "first" {
			for occurrence, eligible := range truth[index] {
				if !eligible {
					continue
				}
				excluded := false
				for _, prior := range selector.Operation.Excluding {
					if selected[prior] == occurrence {
						excluded = true
					}
				}
				if !excluded {
					selected[index] = occurrence
					break
				}
			}
		} else {
			for _, prior := range selector.Operation.Selections {
				if selected[prior] >= 0 {
					selected[index] = selected[prior]
					break
				}
			}
		}
	}
	occurrence := selected[s.Selector]
	if occurrence < 0 {
		return nil, false, nil
	}
	projection := s.Projection
	return (accessorObservation{Plan: projection.Projection, Target: projection.Target, Types: projection.Types}).evaluate(map[string]Node{"item": inputs[s.Plan.Selectors[s.Selector].Input][occurrence]})
}

// Only admitted predicate grammar is visited; payload maps are never interpreted as expressions.
func admitPredicateVersion(value any, major int) error {
	if err := admitPredicateEnvelope(value, 0); err != nil {
		return err
	}
	if major < 8 && predicateNeedsLosslessReader(value) {
		return fmt.Errorf("normalized structured comparison operands require suite/8 or /9")
	}
	if major < 20 && predicateUsesOperator(value, "equals_ignore_case", "in_ignore_case") {
		return fmt.Errorf("case-insensitive text operators require suite/20 or /21")
	}
	if major < 14 && predicateUsesTextMatch(value) {
		return fmt.Errorf("string predicate operators require suite/14 or /15")
	}
	return nil
}

// predicateUsesOperator walks the admitted grammar for a constraint operator named in operators:
// the string operators (beyond10x/ess#95) and the case-insensitive ones (beyond10x/ess#140).
func predicateUsesOperator(value any, operators ...string) bool {
	switch node := value.(type) {
	case []any:
		for _, child := range node {
			if predicateUsesOperator(child, operators...) {
				return true
			}
		}
	case map[string]any:
		for key, child := range node {
			switch key {
			case "all", "and", "all_of", "any", "or", "none", "none_of_these", "not":
				if predicateUsesOperator(child, operators...) {
					return true
				}
			case "forall", "exists":
				if fields, ok := child.(map[string]any); ok && predicateUsesOperator(fields["that"], operators...) {
					return true
				}
			default:
				if constraint, ok := child.(map[string]any); ok {
					for operator := range constraint {
						for _, wanted := range operators {
							if operator == wanted {
								return true
							}
						}
					}
				}
			}
		}
	}
	return false
}

// predicateUsesTextMatch walks the admitted grammar for a string operator (beyond10x/ess#95).
func predicateUsesTextMatch(value any) bool {
	switch node := value.(type) {
	case []any:
		for _, child := range node {
			if predicateUsesTextMatch(child) {
				return true
			}
		}
	case map[string]any:
		for key, child := range node {
			switch key {
			case "all", "and", "all_of", "any", "or", "none", "none_of_these", "not":
				if predicateUsesTextMatch(child) {
					return true
				}
			case "forall", "exists":
				if fields, ok := child.(map[string]any); ok && predicateUsesTextMatch(fields["that"]) {
					return true
				}
			default:
				if operators, ok := child.(map[string]any); ok {
					for operator := range operators {
						switch operator {
						case "starts_with", "ends_with", "contains":
							return true
						}
					}
				}
			}
		}
	}
	return false
}
func predicateNeedsLosslessReader(value any) bool {
	switch node := value.(type) {
	case []any:
		for _, child := range node {
			if predicateNeedsLosslessReader(child) {
				return true
			}
		}
	case map[string]any:
		for key, child := range node {
			switch key {
			case "all", "and", "all_of", "any", "or", "none", "none_of_these", "not":
				if predicateNeedsLosslessReader(child) {
					return true
				}
			case "forall", "exists":
				if fields, ok := child.(map[string]any); ok && predicateNeedsLosslessReader(fields["that"]) {
					return true
				}
			default:
				if operators, ok := child.(map[string]any); ok {
					for operator, value := range operators {
						switch operator {
						case "eq", "equals", "==", "ne", "not_equals", "!=", "lt", "<", "le", "lte", "<=", "gt", ">", "ge", "gte", ">=":
							if raw, ok := value.(string); ok {
								parsed := parseOperand(raw)
								if parsed.isFact || parsed.literal != raw {
									return true
								}
							}
						}
					}
				}
			}
		}
	}
	return false
}

// ---- suite/22 through /35 ----------------------------------------------------------------------
//
// The constructs 0.37.0 and 0.38.0 added to the suite vocabulary (beyond10x/ess#188). Each runs
// the way ess_conformance::runner runs it. A construct a given target cannot answer skips that one
// scenario with the reason, never the suite.

// wallClock is what a `now_offset` value is resolved against: the machine's clock, which is the
// clock the implementation reads its own `now` from. A variable so that a test can hold both sides
// to one instant.
var wallClock = time.Now

// nowOffsetLimit is the largest offset a suite may carry either way, as
// ess_conformance::now_offset::MAX_SECONDS: twice the largest offset a guard may write.
const nowOffsetLimit = 2 * 3155760000

// pageExpectation is a `page` expectation: one page of a paged view (suite/26, beyond10x/ess#174).
type pageExpectation struct {
	Page         uint64       `json:"page"`
	Size         uint64       `json:"size"`
	Rows         uint64       `json:"rows"`
	AtLeast      bool         `json:"at_least"`
	TotalAtLeast *uint64      `json:"total_at_least"`
	Follows      *pageFollows `json:"follows"`
}

// pageFollows is how a page continues the one before it: after that page's last row in the
// declared order, and holding none of its rows again by the named fields.
type pageFollows struct {
	OrderBy    []string `json:"order_by"`
	DistinctBy []string `json:"distinct_by"`
}

// decodeExpectation decodes a view expectation. `changed_by` and `page` are read by their own
// shapes; every other expectation decodes exactly as it did before them.
func decodeExpectation(raw []byte, exact bool) (*Expectation, error) {
	var tag struct {
		Expect string `json:"expect"`
	}
	if err := json.Unmarshal(raw, &tag); err != nil {
		return nil, err
	}
	switch tag.Expect {
	case "changed_by":
		var changed struct {
			Fields       map[string]Node `json:"fields"`
			AbsentIsZero []string        `json:"absent_is_zero"`
		}
		decoder := json.NewDecoder(bytes.NewReader(raw))
		decoder.UseNumber()
		if err := decoder.Decode(&changed); err != nil {
			return nil, err
		}
		return &Expectation{Expect: tag.Expect, Changes: changed.Fields, AbsentIsZero: changed.AbsentIsZero}, nil
	case "page":
		var page pageExpectation
		if err := json.Unmarshal(raw, &page); err != nil {
			return nil, err
		}
		return &Expectation{Expect: tag.Expect, Paged: &page}, nil
	}
	expectation := &Expectation{}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	if exact {
		decoder.UseNumber()
	}
	if err := decoder.Decode(expectation); err != nil {
		return nil, err
	}
	return expectation, nil
}

// sentAs is the caller a command step is sent as: nil for a step that names none.
func sentAs(caller map[string]Node) map[string]Node {
	if len(caller) == 0 {
		return nil
	}
	return caller
}

// executeCommandWithoutInput invokes a command with no input document at all (suite/26,
// `input_absent:`). Everything after it reads its result exactly as after execute_command.
func (r *run) executeCommandWithoutInput(index int, step Step) bool {
	absent, ok := r.target.(AbsentInputTarget)
	if !ok {
		r.skip("step %d: the target cannot send `%s` with no input document (it does not implement AbsentInputTarget)", index, step.Command)
		return false
	}
	if r.replayMode {
		snapshot, err := replaySnapshot(map[string]Node{})
		if err != nil {
			return r.fail(index, "replay input snapshot: %v", err)
		}
		r.lastInput, r.lastActor = snapshot, step.Actor
	}
	result, err := absent.ExecuteCommandWithoutInput(AbsentInputRequest{
		Command:     step.Command,
		Actor:       step.Actor,
		Caller:      sentAs(step.Caller),
		Correlation: r.correlation,
	})
	if errors.Is(err, ErrUnsupported) {
		r.skip("step %d: the target cannot send `%s` with no input: %v", index, step.Command, err)
		return false
	}
	if err != nil {
		return r.targetFailure(index, err, "target callback")
	}
	return r.took(index, step.Command, result)
}

// took records what a command did, for the assertions that read it.
func (r *run) took(index int, command string, result CommandResult) bool {
	if r.disclosure != nil {
		if code := r.disclosure.command(command, result); code != "" {
			return r.disclosureViolation(code)
		}
	}
	if result.Response != nil {
		var err error
		if r.directResponseMode {
			result, err = snapshotDirectResult(result)
		} else {
			result, err = snapshotResponseResult(result)
		}
		if err != nil {
			return r.fail(index, "response observation: %v", err)
		}
	}
	r.consistency = result.Consistency
	r.last = result
	r.lastCommand = command
	// Cleared, not accumulated. Every `expect_no_event` in a scenario is a claim about *this*
	// command — a scenario that creates an invoice and then pays it asserts that paying emitted no
	// `InvoiceCreated`, which would be false against everything seen so far.
	r.observed = map[string][]ObservedEvent{}
	// A refused command published nothing, so nothing a refusal hands back is remembered as seen;
	// `expect_not_granted` fails the refusal for handing it back (beyond10x/ess#265).
	if result.NotGranted {
		return true
	}
	for _, event := range result.DirectEvents {
		r.observed[event.Event] = append(r.observed[event.Event], event)
		r.remember(event)
	}
	return true
}

// fixNowOffsets resolves every `now_offset` the step names that no earlier step of the scenario
// resolved, against one reading of the wall clock rounded up to a whole second: a moment that has
// not yet passed when the target reads its own clock, so a latency under a second cannot move a
// witness across the boundary it sits a second from. Every later `now_offset` of the same number
// in the scenario reads the same instant.
func (r *run) fixNowOffsets(step Step) {
	pending := []int64{}
	visit := func(values map[string]Value) {
		for _, value := range values {
			if value.Kind != "now_offset" {
				continue
			}
			if _, fixed := r.nowFixed[value.Seconds]; fixed {
				continue
			}
			known := false
			for _, seconds := range pending {
				known = known || seconds == value.Seconds
			}
			if !known {
				pending = append(pending, value.Seconds)
			}
		}
	}
	visit(step.Input)
	visit(step.Subject)
	visit(step.Params)
	if step.Expectation != nil {
		visit(step.Expectation.Fields)
	}
	if step.Step == "expect_event_values" {
		if raw, err := json.Marshal(step.Payload); err == nil {
			var values map[string]Value
			if json.Unmarshal(raw, &values) == nil {
				visit(values)
			}
		}
	}
	if len(pending) == 0 {
		return
	}
	now := wallClock().UTC()
	if now.Nanosecond() != 0 {
		now = now.Truncate(time.Second).Add(time.Second)
	}
	if r.nowFixed == nil {
		r.nowFixed = map[int64]string{}
	}
	for _, seconds := range pending {
		instant := now.Add(time.Duration(seconds) * time.Second)
		if instant.Year() < 0 || instant.Year() > 9999 {
			continue
		}
		r.nowFixed[seconds] = instant.Format("2006-01-02T15:04:05Z")
	}
}

// queriedRows is the rows of the last query, when it was a query of view.
func (r *run) queriedRows(index int, view, step string) ([]Row, bool) {
	if r.queried == "" {
		r.fail(index, "no consistent view query preceded `%s`", step)
		return nil, false
	}
	if r.queried != view {
		r.fail(index, "the last query before `%s` names a different view", step)
		return nil, false
	}
	return r.lastView.Rows, true
}

// expectSubjectAbsent requires that the last query of the view holds no row with the removed
// subject's identity (suite/22, `deletes:`).
func (r *run) expectSubjectAbsent(index int, step Step) bool {
	if len(step.Subject) == 0 {
		return r.fail(index, "empty subject identity")
	}
	selected, ok := r.resolveAll(index, step.Subject)
	if !ok {
		return false
	}
	rows, ok := r.queriedRows(index, step.View, "expect_subject_absent")
	if !ok {
		return false
	}
	remaining := 0
	for _, row := range rows {
		carries := true
		for field, value := range selected {
			actual, present := row[field]
			if !present || !equal(actual, value) {
				carries = false
				break
			}
		}
		if carries {
			remaining++
		}
	}
	if remaining != 0 {
		return r.fail(index, "no row of `%s` may carry %s, which the command removed, and %d row(s) still carry it", step.View, describe(selected), remaining)
	}
	return true
}

// copyNode is a deep copy of a value a target returned, so a snapshot cannot change when the
// target reuses what it handed over.
func copyNode(value Node) Node {
	switch value := value.(type) {
	case map[string]any:
		copied := make(map[string]any, len(value))
		for key, item := range value {
			copied[key] = copyNode(item)
		}
		return copied
	case []any:
		copied := make([]any, len(value))
		for i, item := range value {
			copied[i] = copyNode(item)
		}
		return copied
	default:
		return value
	}
}

// snapshotView captures every row of the last query of the view (suite/22, `accepts: nothing`,
// and suite/26 for a change or a page read against it).
func (r *run) snapshotView(index int, step Step) bool {
	rows, ok := r.queriedRows(index, step.View, "snapshot_view")
	if !ok {
		return false
	}
	copied := make([]Row, 0, len(rows))
	for _, row := range rows {
		copied = append(copied, copyNode(map[string]any(row)).(map[string]any))
	}
	if r.viewSnapshots == nil {
		r.viewSnapshots = map[string][]Row{}
	}
	r.viewSnapshots[step.View] = copied
	return true
}

// canonicalRows is a view's rows as a sorted list of their JSON spellings: the same multiset in
// any order reads the same.
func canonicalRows(rows []Row) []string {
	rendered := make([]string, 0, len(rows))
	for _, row := range rows {
		encoded, _ := json.Marshal(row)
		rendered = append(rendered, string(encoded))
	}
	sort.Strings(rendered)
	return rendered
}

// expectViewUnchanged requires the last query of the view to hold exactly the snapshot's rows, in
// any order (suite/22, `accepts: nothing`): a row added, removed or changed is each a failure.
func (r *run) expectViewUnchanged(index int, step Step) bool {
	before, ok := r.viewSnapshots[step.View]
	if !ok {
		return r.fail(index, "no view snapshot preceded this assertion")
	}
	after, ok := r.queriedRows(index, step.View, "expect_view_unchanged")
	if !ok {
		return false
	}
	if !reflect.DeepEqual(canonicalRows(before), canonicalRows(after)) {
		return r.fail(index, "`%s` held %d row(s) before the command and holds %d row(s) after it, not the same ones", step.View, len(before), len(after))
	}
	return true
}

// exactAmount is a number as an exact rational, with an absent value read as zero.
func exactAmount(value Node) (*big.Rat, bool) {
	if value == nil {
		return new(big.Rat), true
	}
	return numberValue(value)
}

// changedBy decides a `changed_by` expectation: the view's one row moved by exactly the stated
// amounts since its snapshot (suite/26, beyond10x/ess#148).
func (r *run) changedBy(step Step) (bool, string, bool) {
	expectation := step.Expectation
	if len(expectation.Changes) == 0 {
		return false, "a change that names no field requires nothing, which is a generator defect", true
	}
	before, ok := r.viewSnapshots[step.View]
	if !ok {
		return false, "no view snapshot preceded this change", true
	}
	rows := r.lastView.Rows
	if len(before) != 1 || len(rows) != 1 {
		return false, fmt.Sprintf("the snapshot held %d row(s) and this read %d; an ungrouped aggregate view holds one", len(before), len(rows)), false
	}
	zero := map[string]bool{}
	for _, field := range expectation.AbsentIsZero {
		zero[field] = true
	}
	fields := make([]string, 0, len(expectation.Changes))
	for field := range expectation.Changes {
		fields = append(fields, field)
	}
	sort.Strings(fields)
	wrong := []string{}
	for _, field := range fields {
		was, now := before[0][field], rows[0][field]
		if !zero[field] && (was == nil || now == nil) {
			wrong = append(wrong, fmt.Sprintf("`%s` was read as %s and then %s; it is never absent: over no row it is 0", field, render(was), render(now)))
			continue
		}
		earlier, ok1 := exactAmount(was)
		later, ok2 := exactAmount(now)
		want, ok3 := numberValue(expectation.Changes[field])
		if !ok1 || !ok2 || !ok3 {
			wrong = append(wrong, fmt.Sprintf("`%s` was read as %s and then %s, which are not both numbers", field, render(was), render(now)))
			continue
		}
		moved := new(big.Rat).Sub(later, earlier)
		if moved.Cmp(want) != 0 {
			wrong = append(wrong, fmt.Sprintf("`%s` changed by %s (%s → %s)", field, moved.RatString(), render(was), render(now)))
		}
	}
	if len(wrong) != 0 {
		return false, fmt.Sprintf("`%s`: %s", step.View, strings.Join(wrong, "; ")), false
	}
	return true, "", false
}

// pageOf decides a `page` expectation (suite/26, beyond10x/ess#174): the page's exact length (or
// a floor on it), a floor on the total, and — for the page after the first — that it continues the
// page before it, which the run snapshotted.
func (r *run) pageOf(step Step) (bool, string, bool) {
	page := step.Expectation.Paged
	if page == nil {
		return false, "the suite names no page, which is a generator defect", true
	}
	if reason := pageDefect(page); reason != "" {
		return false, reason, true
	}
	var before []Row
	if page.Follows != nil {
		snapshot, ok := r.viewSnapshots[step.View]
		if !ok {
			return false, "no view snapshot of the page before preceded this continuation", true
		}
		before = snapshot
	}
	rows := r.lastView.Rows
	held := uint64(len(rows))
	wrong := []string{}
	if page.AtLeast && (held < page.Rows || held > page.Size) {
		wrong = append(wrong, fmt.Sprintf("the page holds %d row(s), and a page of size %d holds at least %d here", held, page.Size, page.Rows))
	} else if !page.AtLeast && held != page.Rows {
		wrong = append(wrong, fmt.Sprintf("the page holds %d row(s), and a page of size %d holds %d here", held, page.Size, page.Rows))
	}
	if page.TotalAtLeast != nil {
		total := r.lastView.Total
		switch {
		case total == nil:
			wrong = append(wrong, "the answer carries no total, and the view declares `total: true`")
		case *total < *page.TotalAtLeast:
			wrong = append(wrong, fmt.Sprintf("the total is %d, fewer than the %d rows this scenario put in the view", *total, *page.TotalAtLeast))
		case *total < held:
			wrong = append(wrong, fmt.Sprintf("the total is %d, fewer than the %d rows the page itself holds", *total, held))
		}
	}
	if page.Follows != nil {
		sequence := []Row{}
		if len(before) > 0 {
			sequence = append(sequence, before[len(before)-1])
		}
		sequence = append(sequence, rows...)
		held, reason, undecidable := ranked(step.View, page.Follows.OrderBy, sequence)
		if undecidable {
			return false, reason, true
		}
		if !held {
			wrong = append(wrong, "the page does not continue the one before it in the declared order: "+reason)
		}
		if len(page.Follows.DistinctBy) > 0 {
			for _, row := range rows {
				for _, earlier := range before {
					again := true
					for _, field := range page.Follows.DistinctBy {
						left, present := earlier[field]
						right, carried := row[field]
						if !present || !carried || !equal(left, right) {
							again = false
							break
						}
					}
					if again {
						wrong = append(wrong, fmt.Sprintf("%s was on the page before it as well", describeRow(row)))
						break
					}
				}
			}
		}
	}
	if len(wrong) != 0 {
		return false, fmt.Sprintf("page %d of `%s`: %s", page.Page, step.View, strings.Join(wrong, "; ")), false
	}
	return true, "", false
}

// pageDefect is why a page expectation is no claim, if it is none, as
// ess_conformance::view_paging::defect words it.
func pageDefect(page *pageExpectation) string {
	switch {
	case page.Size == 0:
		return "a page of size 0 holds no row whatever the target does"
	case page.Rows > page.Size:
		return fmt.Sprintf("a page of size %d cannot hold %d rows, so no target can satisfy it", page.Size, page.Rows)
	case page.TotalAtLeast != nil && *page.TotalAtLeast < page.Rows:
		return fmt.Sprintf("a total of at least %d is less than the %d rows the page itself holds", *page.TotalAtLeast, page.Rows)
	case page.Follows != nil && len(page.Follows.OrderBy) == 0:
		return "a page continues another only in a declared order, and names none"
	}
	return ""
}

// configureRepeatedly forces an external outcome on the next `times` invocations of its command
// (suite/26, a binding's bounded retry).
func (r *run) configureRepeatedly(index int, step Step) bool {
	repeated, ok := r.target.(RepeatedOutcomeTarget)
	if !ok {
		r.skip("step %d: the target cannot force `%s` on the next %d invocations (it does not implement RepeatedOutcomeTarget)", index, step.Force.Outcome, step.Times)
		return false
	}
	err := repeated.ConfigureExternalOutcomeRepeatedly(ExternalOutcomeControl{
		Command:     step.Force.Command,
		Outcome:     step.Force.Outcome,
		Correlation: r.correlation,
	}, step.Times)
	if errors.Is(err, ErrUnsupported) {
		r.skip("step %d: the target cannot force `%s` on the next %d invocations: %v", index, step.Force.Outcome, step.Times, err)
		return false
	}
	if err != nil {
		return r.targetFailure(index, err, "target callback")
	}
	return true
}

// expectInvocationCount requires exactly `count` invocations of the command by the binding,
// observed for the step's whole eventual window: above the count fails at once, and the count is
// decided when the window closes (suite/26, a binding's bounded retry).
func (r *run) expectInvocationCount(index int, step Step, want map[string]Node, absent []string) bool {
	deadline := r.harness.Deadline()
	for attempt := 0; attempt < deadline.Attempts; attempt++ {
		invocations, err := r.target.ObserveInvocations(InvocationObservationRequest{
			Binding:     step.Binding,
			Command:     step.Command,
			Correlation: r.correlation,
			Deadline:    Deadline{Attempts: deadline.Attempts - attempt},
		})
		if errors.Is(err, ErrUnsupported) {
			if r.continuedAssertions {
				return r.unsupportedObservation(index, err)
			}
			r.skip("step %d: the target does not expose what `%s` invoked: %v", index, step.Binding, err)
			return false
		}
		if err != nil {
			return r.targetFailure(index, err, "target callback")
		}
		matching := 0
		for _, invocation := range invocations {
			absenceOK := true
			for _, field := range absent {
				if _, exists := invocation.Input[field]; exists {
					absenceOK = false
				}
			}
			if invocation.Command == step.Command && matches(invocation.Input, want) && absenceOK {
				matching++
			}
		}
		if matching <= step.Count && attempt+1 < deadline.Attempts {
			continue
		}
		if matching != step.Count {
			return r.assertionFailure(index, "ESS-CF-INVOCATION: `%s` invoked `%s` with %s %d time(s) after %d observation(s), and the specification requires exactly %d", step.Binding, step.Command, describe(want), matching, attempt+1, step.Count)
		}
		return true
	}
	return r.assertionFailure(index, "ESS-CF-INVOCATION: `%s` was never observed", step.Binding)
}

// presenceAdmits is ess_conformance::scenario's `LeafShape::admits` for an absent or null value:
// an `Optional` leaf may be left out or null, unless its presence policy forbids that spelling.
func presenceAdmits(expected Held, absent bool) bool {
	if !expected.Optional {
		return false
	}
	if absent {
		return expected.Presence != "null_when_absent"
	}
	return expected.Presence != "omitted_when_absent"
}

// ---- admission of the suite/22–/27 vocabulary ---------------------------------------------------

// admitPositive admits a `times` or `count`: a whole number of at least one that fits a u32.
func admitPositive(value any) error {
	n, err := unsigned(value)
	if err != nil {
		return err
	}
	if n == 0 || n > 4294967295 {
		return fmt.Errorf("a repetition is a whole number of at least 1")
	}
	return nil
}

// admitNowOffset admits a `now_offset` value: exactly `kind` and `seconds`, a whole number of at
// most nowOffsetLimit either way.
func admitNowOffset(value any, major int) error {
	if major < 26 {
		return fmt.Errorf("now_offset values require suite/26 or /27")
	}
	f, err := closed(value, "kind seconds", "")
	if err != nil {
		return err
	}
	number, ok := f["seconds"].(json.Number)
	if !ok {
		return fmt.Errorf("now_offset seconds must be a whole number")
	}
	seconds, err := strconv.ParseInt(string(number), 10, 64)
	if err != nil {
		return fmt.Errorf("now_offset seconds must be a whole number: %w", err)
	}
	if seconds > nowOffsetLimit || seconds < -nowOffsetLimit {
		return fmt.Errorf("now_offset exceeds %d seconds either way", nowOffsetLimit)
	}
	return nil
}

// admitChangedBy admits a `changed_by` expectation: exactly `expect` and `fields`, each amount a
// finite number, and `absent_is_zero` naming only fields the change names.
func admitChangedBy(value any) error {
	f, err := closed(value, "expect fields", "absent_is_zero")
	if err != nil {
		return err
	}
	fields, ok := f["fields"].(map[string]any)
	if !ok || len(fields) == 0 {
		return fmt.Errorf("a change that names no field requires nothing")
	}
	for field, amount := range fields {
		number, ok := amount.(json.Number)
		if !ok {
			return fmt.Errorf("the change of `%s` is not a number", field)
		}
		if parsed, err := strconv.ParseFloat(string(number), 64); err != nil || math.IsInf(parsed, 0) || math.IsNaN(parsed) {
			return fmt.Errorf("the change of `%s` is not a number", field)
		}
	}
	if listed, ok := f["absent_is_zero"]; ok {
		names, err := array(listed)
		if err != nil {
			return err
		}
		for _, entry := range names {
			name, err := text(entry)
			if err != nil {
				return err
			}
			if _, named := fields[name]; !named {
				return fmt.Errorf("`absent_is_zero` names `%s`, which the change does not", name)
			}
		}
	}
	return nil
}

// admitPage admits a `page` expectation: exactly `expect`, `page`, `size` and `rows`, optionally
// `at_least`, `total_at_least` and `follows`, and a page that is some claim.
func admitPage(value any) error {
	f, err := closed(value, "expect page size rows", "at_least total_at_least follows")
	if err != nil {
		return err
	}
	page := &pageExpectation{}
	if page.Page, err = unsigned(f["page"]); err != nil {
		return err
	}
	if page.Size, err = unsigned(f["size"]); err != nil {
		return err
	}
	if page.Rows, err = unsigned(f["rows"]); err != nil {
		return err
	}
	if at, ok := f["at_least"]; ok {
		if _, ok := at.(bool); !ok {
			return fmt.Errorf("at_least must be boolean")
		}
	}
	if total, ok := f["total_at_least"]; ok {
		n, err := unsigned(total)
		if err != nil {
			return err
		}
		page.TotalAtLeast = &n
	}
	if follows, ok := f["follows"]; ok {
		g, err := closed(follows, "order_by", "distinct_by")
		if err != nil {
			return err
		}
		page.Follows = &pageFollows{}
		keys, err := array(g["order_by"])
		if err != nil {
			return err
		}
		for _, key := range keys {
			s, err := text(key)
			if err != nil {
				return err
			}
			page.Follows.OrderBy = append(page.Follows.OrderBy, s)
		}
		if distinct, ok := g["distinct_by"]; ok {
			fields, err := array(distinct)
			if err != nil {
				return err
			}
			for _, field := range fields {
				if _, err := text(field); err != nil {
					return err
				}
			}
		}
	}
	if reason := pageDefect(page); reason != "" {
		return fmt.Errorf("%s", reason)
	}
	return nil
}

// containerHolds is whether value is the container a `list`, `map` or `union` leaf declares, whatever
// Go type a target carries it in: any slice or array for a list, any map for a map or a union.
func containerHolds(holds string, value Node) bool {
	if value == nil {
		return false
	}
	kind := reflect.TypeOf(value).Kind()
	if holds == "list" {
		return kind == reflect.Slice || kind == reflect.Array
	}
	return kind == reflect.Map
}

// containerName is how a container leaf is named in a diagnostic, as the Rust runner names it.
func containerName(holds string) string {
	switch holds {
	case "list":
		return "a list"
	case "map":
		return "a mapping"
	}
	return "a tagged union, as a mapping"
}
